<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { Head, Link, router } from '@inertiajs/vue3'; import { reactive } from 'vue';
const props=defineProps<{events:any[];filters:any;types:string[];statuses:string[];customers:any[];isAdmin:boolean;isSupport:boolean}>(); const filters=reactive({...props.filters}); const apply=()=>router.get(route('events.index'),filters,{preserveState:true,replace:true}); const reset=()=>{filters.search='';filters.event_type='';filters.status='';filters.customer_id='';apply()};
</script>
<template><Head title="Events"/><AuthenticatedLayout><template #header><h2 class="text-xl font-semibold">Events</h2></template><div class="mx-auto max-w-7xl p-6"><Link v-if="isAdmin" :href="route('admin.customers.index')" class="rounded bg-indigo-600 px-3 py-2 text-white">Create Client</Link><form @submit.prevent="apply" class="mt-4 flex flex-wrap gap-2"><input v-model="filters.search" placeholder="Search events" class="rounded border-gray-300"><select v-model="filters.event_type" class="rounded border-gray-300"><option value="">All types</option><option v-for="type in types" :value="type">{{type}}</option></select><select v-if="isAdmin" v-model="filters.status" class="rounded border-gray-300"><option value="">All statuses</option><option v-for="item in statuses" :value="item">{{item}}</option></select><select v-if="isAdmin" v-model="filters.customer_id" class="rounded border-gray-300"><option value="">All clients</option><option v-for="customer in customers" :value="customer.id">{{customer.name}}</option></select><button class="rounded bg-gray-800 px-3 text-white">Search</button><button type="button" @click="reset" class="px-2 text-gray-600">Reset</button></form><div class="mt-4 bg-white shadow sm:rounded"><Link v-for="event in events" :key="event.id" :href="route('events.show', event.id)" class="block border-b p-4 hover:bg-gray-50"><b>{{event.title || 'Invitation setup not completed'}}</b><span class="ml-2 text-sm text-gray-600">{{event.customer?.name}} · {{isAdmin || isSupport ? event.status : event.invitation_status.replaceAll('_', ' ')}}<span v-if="event.live_version"> · Version {{event.live_version}}</span></span></Link><p v-if="!events.length" class="p-4 text-gray-600">No events match your search or filters.</p></div></div></AuthenticatedLayout></template>
